  const [currentPage, setCurrentPage] = useState<number>(1);
  return <Preview onZoomChange={zoom => {
    console.log('zoom-> onZoomChange', zoom);
  }}>
      <PreviewHeader title="Preview " />
      <PreviewBody>
        <Document file="https://cdn.greenloom.ai/traditional-banks-vs-razorpayx.pdf" className="pdf-page">
          <ReactPdfPage key={currentPage} pageNumber={currentPage} width={800} height={700} />
        </Document>
      </PreviewBody>
      <PreviewFooter trailing={<Box display="flex" alignItems="center" gap="spacing.4" borderColor="surface.border.gray.muted" borderWidth="thin" padding="spacing.2" backgroundColor="surface.background.gray.intense" borderRadius="medium">
            <Button icon={ArrowLeftIcon} onClick={() => setCurrentPage(currentPage - 1)} variant="tertiary" aria-label="Zoom in" isDisabled={currentPage <= 1} />
            <Text size="medium" margin="spacing.2">
              {currentPage} / 8
            </Text>
            <Button icon={ArrowRightIcon} onClick={() => setCurrentPage(currentPage + 1)} variant="tertiary" aria-label="Zoom out" isDisabled={currentPage >= 8} />
          </Box>} />
    </Preview>;
